import type { Editor } from "@tiptap/core";

export interface ToolbarComponentProps {
  className?: string;
  editor?: Editor | null;
  size?: "icon" | "icon-lg" | "icon-sm";
}

import CodeBlockBase from "@tiptap/extension-code-block";
import { ReactNodeViewRenderer } from "@tiptap/react";

import { createHighlightPlugin } from "./highlight";
import { CodeBlockView } from "./view";

export { CODE_BLOCK_LANGUAGES } from "./languages";

export const CodeBlock = CodeBlockBase.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      caption: {
        default: null,
        parseHTML: (element) => element.dataset.caption ?? null,
        renderHTML: (attributes) =>
          attributes.caption === null
            ? {}
            : { "data-caption": attributes.caption },
      },
      wrap: {
        default: false,
        parseHTML: (element) => "wrap" in element.dataset,
        renderHTML: (attributes) =>
          attributes.wrap ? { "data-wrap": "" } : {},
      },
    };
  },

  addNodeView() {
    return ReactNodeViewRenderer(CodeBlockView);
  },

  addProseMirrorPlugins() {
    return [...(this.parent?.() ?? []), createHighlightPlugin(this.name)];
  },
}).configure({ defaultLanguage: "javascript" });

"use client";

import type { ReactNodeViewProps } from "@tiptap/react";
import { NodeViewContent, NodeViewWrapper } from "@tiptap/react";
import {
  Braces,
  Captions,
  Check,
  ChevronDown,
  ChevronRight,
  Copy,
  Ellipsis,
  Search,
  Sparkles,
  WrapText,
} from "lucide-react";
import {
  forwardRef,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import type { InputHTMLAttributes, KeyboardEvent, ReactNode } from "react";

import { Button } from "../ui/button";
import { DropdownMenuContent } from "../ui/dropdown-content";
import { DropdownMenuItem } from "../ui/dropdown-item";
import { DropdownMenu } from "../ui/dropdown-menu";
import { Input } from "../ui/input";
import { Popover } from "../ui/popover";
import {
  CODE_BLOCK_LANGUAGES,
  canFormat,
  formatCode,
  getLanguageLabel,
} from "./languages";

type Menu = "actions" | "language" | null;

interface Action {
  icon: ReactNode;
  id: string;
  label: string;
  onSelect: () => void;
  submenu?: boolean;
  trailing?: ReactNode;
}

const useSearchList = <T,>(
  all: T[],
  getLabel: (item: T) => string,
  initialIndex = 0
) => {
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState(initialIndex);
  const [activeItem, setActiveItem] = useState<HTMLElement | null>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const search = query.trim().toLowerCase();
  const items = all.filter((item) =>
    getLabel(item).toLowerCase().includes(search)
  );

  useLayoutEffect(() => {
    const item =
      listRef.current?.querySelectorAll<HTMLElement>(
        ":scope > [data-dropdown-item]"
      )[selected] ?? null;
    setActiveItem(item);
    item?.scrollIntoView({ block: "nearest" });
  }, [search, selected]);

  const move = (delta: number) => {
    if (items.length > 0) {
      setSelected((selected + delta + items.length) % items.length);
    }
  };

  const setSearch = (value: string) => {
    setQuery(value);
    setSelected(0);
  };

  return {
    activeItem: items.length > 0 ? activeItem : null,
    items,
    listRef,
    move,
    query,
    selected,
    setSearch,
    setSelected,
  };
};

const SearchInput = forwardRef<
  HTMLInputElement,
  InputHTMLAttributes<HTMLInputElement>
>((props, ref) => (
  <div className="ext-code-block-search">
    <Search />
    <Input ref={ref} {...props} />
  </div>
));
SearchInput.displayName = "SearchInput";

const LanguageMenu = ({
  value,
  onSelect,
  onBack,
  autoFocus = true,
}: {
  value: string;
  onSelect: (value: string) => void;
  onBack?: () => void;
  autoFocus?: boolean;
}) => {
  const {
    activeItem,
    items,
    listRef,
    move,
    query,
    selected,
    setSearch,
    setSelected,
  } = useSearchList(
    CODE_BLOCK_LANGUAGES,
    (lang) => lang.label,
    Math.max(
      0,
      CODE_BLOCK_LANGUAGES.findIndex((lang) => lang.value === value)
    )
  );
  const inputRef = useRef<HTMLInputElement>(null);
  const listId = useId();

  useEffect(() => {
    if (autoFocus) {
      inputRef.current?.focus();
    }
  }, [autoFocus]);

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      move(event.key === "ArrowDown" ? 1 : -1);
    } else if (event.key === "Enter") {
      event.preventDefault();
      const item = items[selected];
      if (item) {
        onSelect(item.value);
      }
    } else if (event.key === "ArrowLeft" && onBack && query === "") {
      event.preventDefault();
      onBack();
    }
  };

  return (
    <div className="ext-code-block-languages">
      <SearchInput
        ref={inputRef}
        placeholder="Search for a language..."
        aria-label="Search for a language"
        role="combobox"
        aria-controls={listId}
        aria-expanded
        aria-activedescendant={
          items.length > 0 ? `${listId}-${selected}` : undefined
        }
        value={query}
        onChange={(event) => setSearch(event.target.value)}
        onKeyDown={onKeyDown}
      />
      <div className="ext-code-block-menu-label">Languages</div>
      <DropdownMenuContent
        ref={listRef}
        id={listId}
        role="listbox"
        className="ext-code-block-language-list"
        activeItem={activeItem}
      >
        {items.length === 0 && (
          <div className="ext-code-block-menu-label">No results</div>
        )}
        {items.map((lang, index) => (
          <DropdownMenuItem
            key={lang.value}
            id={`${listId}-${index}`}
            role="option"
            aria-selected={lang.value === value}
            onMouseEnter={() => setSelected(index)}
            onClick={() => onSelect(lang.value)}
          >
            <span>{lang.label}</span>
            {lang.value === value && (
              <Check className="ext-code-block-trailing" />
            )}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </div>
  );
};

const ActionsMenu = ({
  actions,
  language,
  onLanguage,
}: {
  actions: Action[];
  language: string;
  onLanguage: (value: string) => void;
}) => {
  const {
    activeItem,
    items,
    listRef,
    move,
    query,
    selected,
    setSearch,
    setSelected,
  } = useSearchList(actions, (action) => action.label);
  const [submenu, setSubmenu] = useState<"focus" | "hover" | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  const run = (action: Action, focus: boolean) => {
    if (action.submenu) {
      setSubmenu(focus ? "focus" : "hover");
    } else {
      action.onSelect();
    }
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    const action = items[selected];
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      setSubmenu(null);
      move(event.key === "ArrowDown" ? 1 : -1);
    } else if (event.key === "Enter" && action) {
      event.preventDefault();
      run(action, true);
    } else if (event.key === "ArrowRight" && action?.submenu) {
      event.preventDefault();
      setSubmenu("focus");
    }
  };

  return (
    <DropdownMenuContent
      ref={listRef}
      className="ext-code-block-actions"
      activeItem={activeItem}
    >
      <SearchInput
        ref={inputRef}
        placeholder="Search actions..."
        aria-label="Search actions"
        value={query}
        onChange={(event) => {
          setSubmenu(null);
          setSearch(event.target.value);
        }}
        onKeyDown={onKeyDown}
      />
      <div className="ext-code-block-menu-label">Code</div>
      {items.length === 0 && (
        <div className="ext-code-block-menu-label">No results</div>
      )}
      {items.map((action, index) => (
        <DropdownMenuItem
          key={action.id}
          aria-haspopup={action.submenu ? "listbox" : undefined}
          aria-expanded={action.submenu ? submenu !== null : undefined}
          onMouseEnter={() => {
            setSelected(index);
            setSubmenu(action.submenu ? "hover" : null);
          }}
          onClick={() => run(action, true)}
        >
          {action.icon}
          {action.label}
          {action.trailing}
        </DropdownMenuItem>
      ))}
      {submenu && (
        <div
          className="ext-code-block-submenu"
          onMouseOver={(event) => event.stopPropagation()}
          onFocus={(event) => event.stopPropagation()}
        >
          <LanguageMenu
            value={language}
            onSelect={onLanguage}
            autoFocus={submenu === "focus"}
            onBack={() => {
              setSubmenu(null);
              inputRef.current?.focus();
            }}
          />
        </div>
      )}
    </DropdownMenuContent>
  );
};

const MermaidPreview = ({ code }: { code: string }) => {
  const id = `ext-mermaid-${useId().replaceAll(/[^a-zA-Z0-9]/g, "")}`;
  const [svg, setSvg] = useState("");
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!code.trim()) {
      return;
    }
    let cancelled = false;
    const timer = setTimeout(async () => {
      try {
        const { default: mermaid } = await import("mermaid");
        mermaid.initialize({
          securityLevel: "strict",
          startOnLoad: false,
          suppressErrorRendering: true,
          theme: document.documentElement.classList.contains("dark")
            ? "dark"
            : "default",
        });
        const result = await mermaid.render(id, code);
        if (!cancelled) {
          setSvg(result.svg);
          setError(null);
        }
      } catch (error_) {
        if (!cancelled) {
          setError(
            error_ instanceof Error
              ? error_.message
              : "Failed to render diagram"
          );
        }
      }
    }, 300);
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [code, id]);

  if (!code.trim()) {
    return null;
  }

  return (
    <div className="ext-code-block-mermaid" contentEditable={false}>
      {error && <div className="ext-code-block-mermaid-error">{error}</div>}
      {!error && svg && (
        <div
          className="ext-code-block-mermaid-svg"
          dangerouslySetInnerHTML={{ __html: svg }}
        />
      )}
      {!error && !svg && (
        <div className="ext-code-block-mermaid-status">
          Rendering diagram...
        </div>
      )}
    </div>
  );
};

export const CodeBlockView = ({
  node,
  editor,
  getPos,
  updateAttributes,
}: ReactNodeViewProps) => {
  const language = (node.attrs.language as string | null) || "plaintext";
  const caption = node.attrs.caption as string | null;
  const code = node.textContent;
  const [editable, setEditable] = useState(editor.isEditable);
  const [menu, setMenu] = useState<Menu>(null);
  const [copied, setCopied] = useState(false);
  const [viewWrap, setViewWrap] = useState<boolean>();
  const wrap = viewWrap ?? Boolean(node.attrs.wrap);
  const captionRef = useRef<HTMLInputElement>(null);
  const focusCaption = useRef(false);

  const openMenu = (next: Menu) => (open: boolean) =>
    setMenu(open ? next : null);

  useEffect(() => {
    const sync = () => setEditable(editor.isEditable);
    editor.on("update", sync);
    return () => {
      editor.off("update", sync);
    };
  }, [editor]);

  useEffect(() => {
    if (focusCaption.current && caption !== null) {
      focusCaption.current = false;
      captionRef.current?.focus();
    }
  }, [caption]);

  useEffect(() => {
    if (!copied) {
      return;
    }
    const timer = setTimeout(() => setCopied(false), 2000);
    return () => clearTimeout(timer);
  }, [copied]);

  const copy = async () => {
    setMenu(null);
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
    } catch {
      setCopied(false);
    }
  };

  const toggleWrap = () => {
    if (editable) {
      updateAttributes({ wrap: !wrap });
    } else {
      setViewWrap(!wrap);
    }
  };

  const setLanguage = (value: string) => {
    setMenu(null);
    updateAttributes({ language: value });
  };

  const addCaption = () => {
    setMenu(null);
    if (caption === null) {
      focusCaption.current = true;
      updateAttributes({ caption: "" });
    } else {
      captionRef.current?.focus();
    }
  };

  const removeCaption = () => {
    updateAttributes({ caption: null });
    const pos = getPos();
    if (typeof pos === "number") {
      editor.commands.focus(pos + node.nodeSize - 1);
    }
  };

  const format = async () => {
    setMenu(null);
    let formatted = code;
    try {
      formatted = await formatCode(code, language);
    } catch {
      return;
    }
    const pos = getPos();
    if (formatted === code || typeof pos !== "number") {
      return;
    }
    const current = editor.state.doc.nodeAt(pos);
    if (current?.textContent !== code) {
      return;
    }
    editor
      .chain()
      .command(({ tr }) => {
        tr.insertText(formatted, pos + 1, pos + current.nodeSize - 1);
        return true;
      })
      .run();
  };

  const actions: Action[] = [
    ...(editable
      ? [
          {
            icon: <Captions />,
            id: "caption",
            label: "Caption",
            onSelect: addCaption,
          },
        ]
      : []),
    { icon: <Copy />, id: "copy", label: "Copy code", onSelect: copy },
    {
      icon: <WrapText />,
      id: "wrap",
      label: "Wrap code",
      onSelect: toggleWrap,
      trailing: (
        <span
          className="ext-code-block-switch ext-code-block-trailing"
          data-checked={wrap ? "" : undefined}
        />
      ),
    },
    ...(editable
      ? [
          {
            icon: <Braces />,
            id: "language",
            label: "Language",
            onSelect: () => setMenu("language"),
            submenu: true,
            trailing: <ChevronRight className="ext-code-block-trailing" />,
          },
        ]
      : []),
    ...(editable && canFormat(language)
      ? [
          {
            icon: <Sparkles />,
            id: "format",
            label: "Format code",
            onSelect: format,
          },
        ]
      : []),
  ];

  return (
    <NodeViewWrapper className="ext-code-block" data-language={language}>
      <div className="ext-code-block-box">
        <div
          className="ext-code-block-header"
          contentEditable={false}
          data-open={menu ? "" : undefined}
        >
          {editable ? (
            <DropdownMenu
              open={menu === "language"}
              onOpenChange={openMenu("language")}
              trigger={
                <Button className="ext-code-block-lang">
                  {getLanguageLabel(language)}
                  <ChevronDown />
                </Button>
              }
            >
              <LanguageMenu value={language} onSelect={setLanguage} />
            </DropdownMenu>
          ) : (
            <span className="ext-code-block-lang">
              {getLanguageLabel(language)}
            </span>
          )}
          <div className="ext-code-block-toolbar">
            <Button
              className="ext-btn--icon-sm"
              aria-label="Copy"
              tooltip="Copy"
              onClick={copy}
            >
              {copied ? <Check /> : <Copy />}
            </Button>
            {editable && (
              <Button
                className="ext-btn--icon-sm"
                aria-label="Caption"
                tooltip="Caption"
                onClick={addCaption}
              >
                <Captions />
              </Button>
            )}
            <Popover
              align="end"
              open={menu === "actions"}
              onOpenChange={openMenu("actions")}
              trigger={
                <Button className="ext-btn--icon-sm" aria-label="More">
                  <Ellipsis />
                </Button>
              }
            >
              <ActionsMenu
                actions={actions}
                language={language}
                onLanguage={setLanguage}
              />
            </Popover>
          </div>
        </div>
        <pre spellCheck={false}>
          <NodeViewContent<"code">
            as="code"
            style={{ whiteSpace: wrap ? "pre-wrap" : "pre" }}
          />
        </pre>
        {language === "mermaid" && <MermaidPreview code={code} />}
      </div>
      {caption !== null && (
        <div className="ext-code-block-caption" contentEditable={false}>
          {editable ? (
            <input
              ref={captionRef}
              aria-label="Caption"
              placeholder="Write a caption..."
              value={caption}
              onChange={(event) =>
                updateAttributes({ caption: event.target.value })
              }
              onKeyDown={(event) => {
                if (event.key === "Backspace" && caption === "") {
                  event.preventDefault();
                  removeCaption();
                }
              }}
            />
          ) : (
            caption
          )}
        </div>
      )}
    </NodeViewWrapper>
  );
};

import type { Node as PMNode } from "@tiptap/pm/model";
import { Plugin, PluginKey } from "@tiptap/pm/state";
import { Decoration, DecorationSet } from "@tiptap/pm/view";
import type { BundledLanguage, BundledTheme, HighlighterGeneric } from "shiki";

type Highlighter = HighlighterGeneric<BundledLanguage, BundledTheme>;
interface Token {
  from: number;
  to: number;
  style: string;
}

const THEMES = { dark: "github-dark", light: "github-light" } as const;
const PLAIN = new Set(["plaintext", "text", "txt", "plain"]);

let highlighter: Highlighter | undefined;
let highlighterPromise: Promise<Highlighter> | undefined;
const requested = new Set<string>();
const listeners = new Set<() => void>();
const cache = new WeakMap<PMNode, Token[]>();

const createShikiHighlighter = async () => {
  try {
    const { createHighlighter } = await import("shiki");
    highlighter = await createHighlighter({
      langs: [],
      themes: [THEMES.light, THEMES.dark],
    });
    return highlighter;
  } catch (error) {
    highlighterPromise = undefined;
    throw error;
  }
};

const requestLanguage = async (language: string) => {
  if (requested.has(language)) {
    return;
  }
  requested.add(language);
  try {
    highlighterPromise ??= createShikiHighlighter();
    const instance = await highlighterPromise;
    const { bundledLanguages } = await import("shiki");
    if (language in bundledLanguages) {
      await instance.loadLanguage(language as BundledLanguage);
    }
    for (const listener of listeners) {
      listener();
    }
  } catch {
    requested.delete(language);
  }
};

const tokenize = (node: PMNode): Token[] => {
  const cached = cache.get(node);
  if (cached) {
    return cached;
  }
  const language = (node.attrs.language as string | null) || "plaintext";
  if (PLAIN.has(language)) {
    return [];
  }
  if (!highlighter?.getLoadedLanguages().includes(language)) {
    void requestLanguage(language);
    return [];
  }
  const { tokens } = highlighter.codeToTokens(node.textContent, {
    defaultColor: false,
    lang: language as BundledLanguage,
    themes: THEMES,
  });
  const result = tokens.flat().flatMap((token) =>
    token.htmlStyle
      ? [
          {
            from: token.offset,
            style: Object.entries(token.htmlStyle)
              .map(([key, value]) => `${key}:${value}`)
              .join(";"),
            to: token.offset + token.content.length,
          },
        ]
      : []
  );
  cache.set(node, result);
  return result;
};

const buildDecorations = (doc: PMNode, typeName: string) => {
  const decorations: Decoration[] = [];
  doc.descendants((node, pos) => {
    if (node.type.name !== typeName) {
      return true;
    }
    for (const token of tokenize(node)) {
      decorations.push(
        Decoration.inline(pos + 1 + token.from, pos + 1 + token.to, {
          style: token.style,
        })
      );
    }
    return false;
  });
  return DecorationSet.create(doc, decorations);
};

const highlightKey = new PluginKey<DecorationSet>("codeBlockHighlight");

export const createHighlightPlugin = (typeName: string) =>
  new Plugin<DecorationSet>({
    key: highlightKey,
    props: {
      decorations: (state) => highlightKey.getState(state),
    },
    state: {
      apply: (tr, set) =>
        tr.docChanged || tr.getMeta(highlightKey)
          ? buildDecorations(tr.doc, typeName)
          : set,
      init: (_, { doc }) => buildDecorations(doc, typeName),
    },
    view: (view) => {
      const refresh = () => {
        if (!view.isDestroyed) {
          view.dispatch(view.state.tr.setMeta(highlightKey, true));
        }
      };
      listeners.add(refresh);
      return { destroy: () => listeners.delete(refresh) };
    },
  });

