  display: block;
  padding: 0;
  background: none;
  border: none;
  border-radius: 0;
  color: inherit;
  font-family: inherit;
  font-size: inherit;
  font-weight: 400;
  word-break: normal;
  overflow-wrap: anywhere;
}

.ext-code-block code span[style] {
  color: var(--shiki-light);
}

.dark .ext-code-block code span[style] {
  color: var(--shiki-dark);
}

.ext-code-block-header {
  position: absolute;
  inset: 0.375rem 0.375rem auto 0.5rem;
  z-index: 10;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  pointer-events: none;
  opacity: 0;
  transition: opacity 150ms ease-out;
}

.ext-code-block-box:hover .ext-code-block-header,
.ext-code-block-header:focus-within,
.ext-code-block-header[data-open] {
  opacity: 1;
}

.ext-code-block-header > * {
  pointer-events: auto;
}

.ext-btn.ext-code-block-lang,
span.ext-code-block-lang {
  height: 1.25rem;
  gap: 0.125rem;
  padding: 0 0.375rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
  font-weight: 400;
}

span.ext-code-block-lang {
  display: inline-flex;
  align-items: center;
}

.ext-btn.ext-code-block-lang > svg {
  width: 0.75rem;
  height: 0.75rem;
}

.ext-code-block-toolbar {
  display: flex;
  gap: 0.125rem;
  color: var(--muted-foreground);
}

.ext-code-block-toolbar .ext-btn {
  width: 1.5rem;
  height: 1.5rem;
  border-radius: calc(var(--radius) - 4px);
}

.ext-code-block-toolbar .ext-btn > svg {
  width: 0.875rem;
  height: 0.875rem;
}

.ext-code-block-languages {
  width: 15rem;
  padding: 0 0.25rem 0.25rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--popover);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.ext-dropdown-content.ext-code-block-language-list {
  min-width: 0;
  max-height: 15rem;
  overflow-y: auto;
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  animation: none;
}

.ext-code-block-language-list::-webkit-scrollbar {
  width: 6px;
}

.ext-code-block-language-list::-webkit-scrollbar-track,
.ext-code-block-language-list::-webkit-scrollbar-button {
  display: none;
  background: transparent;
}

.ext-code-block-language-list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: var(--border);
}

.ext-code-block-language-list::-webkit-scrollbar-thumb:hover {
  background: var(--muted-foreground);
}

@supports not selector(::-webkit-scrollbar) {
  .ext-code-block-language-list {
    scrollbar-width: thin;
    scrollbar-color: var(--border) transparent;
  }
}

.ext-code-block-search {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  margin: 0 -0.25rem;
  padding: 0.25rem;
  background: var(--popover);
}

.ext-code-block-search > svg {
  position: absolute;
  left: 0.75rem;
  width: 0.875rem;
  height: 0.875rem;
  color: var(--muted-foreground);
  pointer-events: none;
}

.ext-code-block-search .ext-input {
  height: 2rem;
  padding-left: 1.75rem;
}

.ext-code-block-submenu {
  position: absolute;
  top: 2.5rem;
  right: calc(100% + 0.5rem);
}

.ext-code-block-menu-label {
  padding: 0.375rem 0.5rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.ext-code-block-actions {
  width: 16rem;
  padding-top: 0;
}

.ext-code-block-trailing {
  margin-left: auto;
}

.ext-code-block-switch {
  position: relative;
  width: 1.75rem;
  height: 1rem;
  border-radius: 999px;
  background: var(--input);
  transition: background-color 150ms ease-out;
}

.ext-code-block-switch::after {
  content: "";
  position: absolute;
  top: 0.125rem;
  left: 0.125rem;
  width: 0.75rem;
  height: 0.75rem;
  border-radius: 999px;
  background: var(--background);
  transition: transform 150ms ease-out;
}

.ext-code-block-switch[data-checked] {
  background: var(--primary);
}

.ext-code-block-switch[data-checked]::after {
  transform: translateX(0.75rem);
}

.ext-code-block-mermaid {
  display: flex;
  justify-content: center;
  padding: 0 1.25rem 1.25rem;
  overflow: auto;
}

.ext-code-block-mermaid-svg svg {
  max-width: 100%;
  height: auto;
}

.ext-code-block-mermaid-error,
.ext-code-block-mermaid-status {
  font-size: 0.75rem;
}

.ext-code-block-mermaid-error {
  color: var(--destructive);
}

.ext-code-block-mermaid-status {
  padding: 1rem 0;
  color: var(--muted-foreground);
}

.ext-code-block-caption {
  padding: 0.375rem 0.125rem;
  color: var(--muted-foreground);
  font-size: 0.875rem;
  line-height: 1.4;
}

.ext-code-block-caption input {
  width: 100%;
  padding: 0;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  outline: none;
}

/* Extensions UI primitives using shadcn CSS variables */

@keyframes ext-pop-in {
  from {
    opacity: 0;
    translate: 0 0.25rem;
    scale: 0.95;
  }
  to {
    opacity: 1;
    translate: 0 0;
    scale: 1;
  }
}

/* ── Button ── */
.ext-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 0.375rem;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid transparent;
  border-radius: calc(var(--radius) - 2px);
  background: transparent;
  color: inherit;
  font-size: 0.8125rem;
  font-family: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  outline: none;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    border-color 150ms ease-out,
    transform 100ms ease-out;
}

.ext-btn > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-btn--icon {
  width: 2rem;
  padding: 0;
}

.ext-btn--icon-sm {
  width: 1.75rem;
  padding: 0;
}

.ext-btn:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-btn:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}

.ext-btn:active {
  transform: scale(0.96);
}

.ext-btn:disabled {
  pointer-events: none;
  opacity: 0.5;
}

.ext-btn--active {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-btn--danger {
  color: var(--destructive, #ef4444);
}

.ext-btn--danger:hover {
  background: color-mix(in srgb, var(--destructive, #ef4444) 10%, transparent);
  color: var(--destructive, #ef4444);
}

/* ── Dropdown ── */
.ext-dropdown-content {
  position: relative;
  min-width: 10rem;
  padding: 0.25rem;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.ext-dropdown-item {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.375rem 0.5rem;
  border: none;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: var(--popover-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out,
    transform 100ms ease-out;
}

.ext-dropdown-item > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-dropdown-pill {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: calc(var(--radius) - 4px);
  background: color-mix(in srgb, var(--primary) 6%, transparent);
  opacity: 0;
  transition:
    top 220ms cubic-bezier(0.22, 1, 0.36, 1),
    left 220ms cubic-bezier(0.22, 1, 0.36, 1),
    width 220ms cubic-bezier(0.22, 1, 0.36, 1),
    height 220ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 150ms ease-out;
}

.ext-dropdown-pill--visible {
  opacity: 1;
}

.ext-dropdown-item:hover,
.ext-dropdown-item:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-dropdown-item:active {
  transform: scale(0.98);
}

.ext-dropdown-item:disabled {
  pointer-events: none;
  opacity: 0.5;
}

.ext-dropdown-item--danger {
  color: var(--destructive, #ef4444);
}

.ext-dropdown-item--danger:hover,
.ext-dropdown-item--danger:focus-visible {
  background: color-mix(in srgb, var(--destructive, #ef4444) 10%, transparent);
  color: var(--destructive, #ef4444);
}

.ext-dropdown-separator {
  height: 1px;
  background: var(--border);
  margin: 0.25rem 0;
}

/* ── Popover ── */
.ext-popover-content {
  position: relative;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* ── Tooltip ── */
.ext-tooltip {
  padding: 0.375rem 0.75rem;
  border-radius: 0;
  background: var(--foreground);
  color: var(--background);
  font-size: 0.75rem;
  line-height: 1rem;
  white-space: nowrap;
  pointer-events: none;
  animation: ext-pop-in 0.12s ease-out forwards;
}

/* ── Separator ── */
.ext-separator {
  flex-shrink: 0;
  background: var(--border);
}

.ext-separator--horizontal {
  height: 1px;
  margin: 0.25rem 0;
}

.ext-separator--vertical {
  width: 1px;
  height: 1rem;
  align-self: center;
  margin: 0 0.25rem;
}

/* ── Input ── */
.ext-input {
  width: 100%;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) - 2px);
  background: var(--background);
  color: var(--foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  outline: none;
  transition:
    border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}

.ext-input::placeholder {
  color: var(--muted-foreground);
}

.ext-input:focus-visible {
  border-color: var(--ring);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--ring) 30%, transparent);
}

/* ── Tabs ── */
.ext-tabs {
  display: flex;
  flex-direction: column;
}

.ext-tabs-list {
  display: flex;
  gap: 0.125rem;
  width: fit-content;
  padding: 0.25rem;
  border-radius: calc(var(--radius) - 4px);
  background: var(--muted);
}

.ext-tabs-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.625rem;
  border: none;
  border-radius: calc(var(--radius) - 6px);
  background: transparent;
  color: var(--muted-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out;
}

.ext-tabs-trigger > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-tabs-trigger:hover,
.ext-tabs-trigger:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-tabs-trigger--active {
  background: var(--background);
  color: var(--foreground);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
}

.ext-tabs-content {
  padding-top: 0.5rem;
}
